    patches = []
    for object in objects:
        object_patches = image_patch.find(object)
        if object_patches:
            patches.extend(object_patches)
    return patches

def answer_query(image, query):
    objects = query.split()
    patches = find_objects(image, objects)
    if not patches:
        return "None of the objects were found in the image."

    # If the objects are found, return the answer to the question using llm_query
    object_names = ' '.join([patch.simple_query() for patch in patches])
